mapper.select:
SELECT ,
       s.name AS student_name, s.student_no AS student_no,
       u.real_name AS counselor_name
FROM student_record f
LEFT JOIN student s ON f.student_id = s.id
LEFT JOIN sys_user u ON f.counselor_id = u.id

    f.record_type = 'AID'
    AND s.name LIKE CONCAT('%', #{studentName}, '%')
    AND f.category = #{aidType}
    AND f.difficulty_level = #{difficultyLevel}
    AND f.status = #{status}
    AND f.student_id = #{studentId}
    AND f.counselor_id = #{counselorId}

ORDER BY f.create_time DESC, f.id DESC

mapper.update:
UPDATE student_record
student_id = #{studentId}, category = #{aidType}, amount = #{amount}, semester = #{semester}, family_income = #{familyIncome}, difficulty_level = #{difficultyLevel}, reason = #{reason}, status = #{status}, counselor_id = #{counselorId},
WHERE record_type = 'AID' AND id = #{id}
